from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM
from exo.core.extern import Extern, _EErr
from exo.API_cursors import ForCursor, InvalidCursor


# Extern for exp()
class _Exp(Extern):
    def __init__(self):
        super().__init__("exp")

    def typecheck(self, args):
        if len(args) != 1:
            raise _EErr(f"expected 1 argument, got {len(args)}")

        arg_type = args[0].type
        if not arg_type.is_real_scalar():
            raise _EErr(
                f"expected argument to be a real scalar value, but got type {arg_type}"
            )
        return arg_type

    def compile(self, args, prim_type):
        return f"exp(({prim_type}){args[0]})"

    def globl(self, prim_type):
        return "#include <math.h>"

    def interpret(self, args):
        import math
        return math.exp(args[0])


# Extern for pow()
class _Pow(Extern):
    def __init__(self):
        super().__init__("pow")

    def typecheck(self, args):
        if len(args) != 2:
            raise _EErr(f"expected 2 arguments, got {len(args)}")

        arg_type0 = args[0].type
        arg_type1 = args[1].type
        if not arg_type0.is_real_scalar() or not arg_type1.is_real_scalar():
            raise _EErr(
                f"expected arguments to be real scalar values, but got types {arg_type0}, {arg_type1}"
            )
        return arg_type0

    def compile(self, args, prim_type):
        return f"pow(({prim_type}){args[0]}, ({prim_type}){args[1]})"

    def globl(self, prim_type):
        return "#include <math.h>"

    def interpret(self, args):
        import math
        return math.pow(args[0], args[1])


exp = _Exp()
pow = _Pow()


@proc
def kernel_deriche(
    w: size,
    h: size,
    alpha: DATA_TYPE,
    imgIn: DATA_TYPE[w, h] @ DRAM,
    imgOut: DATA_TYPE[w, h] @ DRAM,
    y1: DATA_TYPE[w, h] @ DRAM,
    y2: DATA_TYPE[w, h] @ DRAM,
):
    # Temporary state along each scanline
    xm1: DATA_TYPE
    tm1: DATA_TYPE
    ym1: DATA_TYPE
    ym2: DATA_TYPE
    xp1: DATA_TYPE
    xp2: DATA_TYPE
    tp1: DATA_TYPE
    tp2: DATA_TYPE
    yp1: DATA_TYPE
    yp2: DATA_TYPE

    # Coefficients and precomputed exponentials
    ema: DATA_TYPE
    em2a: DATA_TYPE
    ep2a: DATA_TYPE
    k: DATA_TYPE
    a1: DATA_TYPE
    a2: DATA_TYPE
    a3: DATA_TYPE
    a4: DATA_TYPE
    a5: DATA_TYPE
    a6: DATA_TYPE
    a7: DATA_TYPE
    a8: DATA_TYPE
    b1: DATA_TYPE
    b2: DATA_TYPE
    c1: DATA_TYPE
    c2: DATA_TYPE

    # Precompute exponentials to avoid redundant exp() calls
    ema = exp(-alpha)
    em2a = exp(-2.0 * alpha)
    ep2a = exp(2.0 * alpha)

    # Coefficient computation (same formula as original kernel)
    k = (1.0 - ema) * (1.0 - ema) / (1.0 + 2.0 * alpha * ema - ep2a)
    a1 = k
    a5 = k
    a2 = k * ema * (alpha - 1.0)
    a6 = a2
    a3 = k * ema * (alpha + 1.0)
    a7 = a3
    a4 = -k * em2a
    a8 = a4
    b1 = pow(2.0, -alpha)
    b2 = -em2a
    c1 = 1.0
    c2 = 1.0

    # Vertical forward pass (per row, forward along columns)
    for i in seq(0, w):
        ym1 = 0.0
        ym2 = 0.0
        xm1 = 0.0
        for j in seq(0, h):
            y1[i, j] = a1 * imgIn[i, j] + a2 * xm1 + b1 * ym1 + b2 * ym2
            xm1 = imgIn[i, j]
            ym2 = ym1
            ym1 = y1[i, j]

    # Vertical backward pass (per row, backward along columns)
    for i in seq(0, w):
        yp1 = 0.0
        yp2 = 0.0
        xp1 = 0.0
        xp2 = 0.0
        for j in seq(0, h):
            y2[i, h - 1 - j] = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2
            xp2 = xp1
            xp1 = imgIn[i, h - 1 - j]
            yp2 = yp1
            yp1 = y2[i, h - 1 - j]

    # Combine vertical forward and backward passes
    for i in seq(0, w):
        for j in seq(0, h):
            imgOut[i, j] = c1 * (y1[i, j] + y2[i, j])

    # Horizontal forward pass (per column, forward along rows)
    for j in seq(0, h):
        tm1 = 0.0
        ym1 = 0.0
        ym2 = 0.0
        for i in seq(0, w):
            y1[i, j] = a5 * imgOut[i, j] + a6 * tm1 + b1 * ym1 + b2 * ym2
            tm1 = imgOut[i, j]
            ym2 = ym1
            ym1 = y1[i, j]

    # Horizontal backward pass (per column, backward along rows)
    for j in seq(0, h):
        tp1 = 0.0
        tp2 = 0.0
        yp1 = 0.0
        yp2 = 0.0
        for i in seq(0, w):
            y2[w - 1 - i, j] = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2
            tp2 = tp1
            tp1 = imgOut[w - 1 - i, j]
            yp2 = yp1
            yp1 = y2[w - 1 - i, j]

    # Final combine of horizontal passes
    for i in seq(0, w):
        for j in seq(0, h):
            imgOut[i, j] = c2 * (y1[i, j] + y2[i, j])


# -------------------------------
# Scheduling / optimization
# -------------------------------

# Tunable tile size for the inner image dimension (columns).
# This is used to tile the j-loops of the 2D combine phases to
# improve cache reuse along the contiguous dimension.
TILE_J: int = 32

p = kernel_deriche

# Tile the j-loop of the vertical combine pass:
# for i in 0..w:
#   for j in 0..h:
#     imgOut[i,j] = ...
#
# This keeps the same semantics but processes columns in TILE_J-sized
# chunks, which can improve spatial locality in some cache hierarchies.
i_vcomb = p.find_loop("i #2")
j_vcomb = i_vcomb.body().find_loop("j")
p = divide_loop(p, j_vcomb, TILE_J, ("jo_v", "ji_v"), tail="guard")

# Tile the j-loop of the final 2D combine:
# for i in 0..w:
#   for j in 0..h:
#     imgOut[i,j] = ...
i_final = p.find_loop("i #5")
j_final = i_final.body().find_loop("j")
p = divide_loop(p, j_final, TILE_J, ("jo_f", "ji_f"), tail="guard")

# Parallelize all top-level loops over rows/columns. Each of these
# outer loops is independent across its iteration space, so Exo's
# dependence analysis will allow them to be mapped to OpenMP
# parallel for loops on the C backend.
all_loops = p.find_all("for _ in _:_")
top_level_loops = []
for loop in all_loops:
    if isinstance(loop.parent(), InvalidCursor):
        top_level_loops.append(loop)

for loop in top_level_loops:
    p = parallelize_loop(p, loop)

# Perform algebraic simplification and dead-code elimination after
# structural loop transformations.
p = simplify(p)

# Export the optimized version under the original name so that the
# generated C function has the expected symbol `kernel_deriche`.
kernel_deriche = p
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int w = W;
  int h = H;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(imgIn, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(imgOut, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y1, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y2, DATA_TYPE, W, H, w, h);

  /* Initialize array(s). */
  init_array (w, h, &alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_deriche(/*ctxt=*/NULL,
                 w, h,
                 (DATA_TYPE*)&alpha,
                 (DATA_TYPE*)POLYBENCH_ARRAY(imgIn),
                 (DATA_TYPE*)POLYBENCH_ARRAY(imgOut),
                 (DATA_TYPE*)POLYBENCH_ARRAY(y1),
                 (DATA_TYPE*)POLYBENCH_ARRAY(y2));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(w, h, POLYBENCH_ARRAY(imgOut)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(imgIn);
  POLYBENCH_FREE_ARRAY(imgOut);
  POLYBENCH_FREE_ARRAY(y1);
  POLYBENCH_FREE_ARRAY(y2);

  return 0;
}

